import{_ as r,o as e,c as a,ak as n}from"./chunks/framework.CMX7UUIo.js";const u=JSON.parse('{"title":"Wheat Flour","description":"","frontmatter":{"title":"Wheat Flour"},"headers":[],"relativePath":"en/crops/wheat/wheat-flour.md","filePath":"en/crops/wheat/wheat-flour.md"}'),o={name:"en/crops/wheat/wheat-flour.md"};function i(d,t,s,l,h,g){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="wheat-flour" tabindex="-1">Wheat Flour <a class="header-anchor" href="#wheat-flour" aria-label="Permalink to “Wheat Flour”">​</a></h1><p>Wheat flour is produced by grinding wheat, partially or completely removing bran and germ, and is used to make wheat-based food products.</p><h2 id="nutritional-value" tabindex="-1">Nutritional Value <a class="header-anchor" href="#nutritional-value" aria-label="Permalink to “Nutritional Value”">​</a></h2><p>Wheat flour contains <a href="https://en.wikipedia.org/wiki/Protein" target="_blank" rel="noreferrer">protein</a>, <a href="https://en.wikipedia.org/wiki/Starch" target="_blank" rel="noreferrer">starch</a>, <a href="https://en.wikipedia.org/wiki/Fat" target="_blank" rel="noreferrer">fat</a>, <a href="https://en.wikipedia.org/wiki/Vitamin" target="_blank" rel="noreferrer">vitamins</a>, and inorganic salts. The protein content in wheat flour is higher than other grain products, generally above 11%, and can reach as high as 15%-20%. It consists of <a href="https://en.wikipedia.org/wiki/Gliadin" target="_blank" rel="noreferrer">gliadin</a> and <a href="https://en.wikipedia.org/wiki/Glutenin" target="_blank" rel="noreferrer">glutenin</a>, which can form elastic gluten when absorbing water. Therefore, wheat flour can be used to make foods with unique quality and <a href="https://en.wikipedia.org/wiki/Flavor" target="_blank" rel="noreferrer">flavor</a>. The <a href="https://en.wikipedia.org/wiki/Carbohydrate" target="_blank" rel="noreferrer">carbohydrate</a> content in wheat flour is above 70%, mainly consisting of starch, cellulose, and other <a href="https://en.wikipedia.org/wiki/Sugar" target="_blank" rel="noreferrer">sugars</a>, which are the main sources of energy for the human body.</p><h2 id="quality-standards" tabindex="-1">Quality Standards <a class="header-anchor" href="#quality-standards" aria-label="Permalink to “Quality Standards”">​</a></h2><p>Wheat flour is generally divided into three categories: <strong>Premium Flour</strong>, <strong>Standard Flour</strong>, and <strong>All-Purpose Flour</strong>. The classification is based on various quality indicators in the current national standard <a href="https://openstd.samr.gov.cn/bzgk/gb/newGbInfo?hcno=7FBA509CDA87E5C9DE846BBC077430B4&amp;refer=outter" target="_blank" rel="noreferrer">GB/T 1355-2021</a> (implemented 2023-01-01), including: <strong>milling precision</strong> (the degree of bran residue in wheat flour), <strong>ash content</strong> (dry basis), <strong>fatty acid value</strong> (wet basis, KOH), <strong>moisture content</strong>, <strong>sand content</strong>, <strong>magnetic metal particles</strong>, <strong>color</strong>, <strong>odor</strong>, <strong>appearance</strong>, and <strong>wet gluten content</strong>.</p><table tabindex="0"><thead><tr><th>Quality Standard</th><th>Premium Flour</th><th>Standard Flour</th><th>All-Purpose Flour</th></tr></thead><tbody><tr><td>Milling Precision</td><td>Check bran specks by comparing with standard samples or instrument readings</td><td></td><td></td></tr><tr><td>Ash Content/%</td><td>≤0.70</td><td>≤1.10</td><td>≤1.60</td></tr><tr><td>Fatty Acid Value/(mg/100g)</td><td>≤80</td><td></td><td></td></tr><tr><td>Moisture Content/%</td><td>≤14.5</td><td></td><td></td></tr><tr><td>Sand Content/%</td><td>≤0.02</td><td></td><td></td></tr><tr><td>Magnetic Metal/(g/kg)</td><td>≤0.003</td><td></td><td></td></tr><tr><td>Color, Odor</td><td>Normal</td><td></td><td></td></tr><tr><td>Appearance</td><td>Powdery or granular, no caking</td><td></td><td></td></tr><tr><td>Wet Gluten Content/%</td><td>≥22.0</td><td></td><td></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Source: GB/T 1355-2021</p></div>',8)])])}const p=r(o,[["render",i]]);export{u as __pageData,p as default};
